insert into public.quiz (id, country_code, titre, version, publie) values
  (10001, 'BJ', 'Testez-vous · Bénin 2026', 1, false);
insert into public.statement (id, quiz_id, ordre, texte, theme) values
  (10001, 10001, 1, 'La réforme du système partisan de 2018, qui a conduit au regroupement des partis, doit être maintenue telle quelle.', 'institutions'),
  (10002, 10001, 2, 'Le Sénat créé par la révision constitutionnelle de 2025 doit être conservé.', 'institutions'),
  (10003, 10001, 3, 'Chaque circonscription électorale doit continuer à réserver un siège de député aux femmes.', 'institutions'),
  (10004, 10001, 4, 'Les Béninois vivant à l''étranger doivent élire leurs propres députés.', 'institutions'),
  (10005, 10001, 5, 'Un gouvernement d''union nationale doit être formé.', 'institutions'),
  (10006, 10001, 6, 'La loi qui reconnaît les chefferies traditionnelles doit être appliquée telle qu''elle a été votée.', 'institutions'),
  (10007, 10001, 7, 'La CRIET, juridiction spéciale chargée des infractions économiques et du terrorisme, doit être maintenue.', 'justice'),
  (10008, 10001, 8, 'Les personnalités politiques condamnées ces dernières années doivent être libérées.', 'justice'),
  (10009, 10001, 9, 'Les sanctions pénales prévues pour les délits de presse doivent être maintenues.', 'libertes'),
  (10010, 10001, 10, 'Le droit de grève doit rester encadré dans la santé et dans l''éducation.', 'libertes'),
  (10011, 10001, 11, 'L''État doit laisser une place plus importante au secteur privé dans l''économie.', 'economie'),
  (10012, 10001, 12, 'Le port de Cotonou doit rester géré par un opérateur privé.', 'economie'),
  (10013, 10001, 13, 'Une part des marchés publics doit être réservée aux entreprises béninoises.', 'economie'),
  (10014, 10001, 14, 'Le secteur informel doit contribuer davantage à l''impôt.', 'economie'),
  (10015, 10001, 15, 'Les prix des produits agricoles d''exportation doivent être fixés avec les organisations de producteurs.', 'agriculture'),
  (10016, 10001, 16, 'Les langues nationales doivent être enseignées à l''école.', 'education'),
  (10017, 10001, 17, 'Les aspirants au métier d''enseignant (AME) doivent être intégrés comme agents de l''État.', 'education'),
  (10018, 10001, 18, 'La restauration, le transport et l''hébergement universitaires doivent être confiés au secteur privé.', 'education'),
  (10019, 10001, 19, 'Les écoles doivent continuer à appliquer l''approche par compétences.', 'education'),
  (10020, 10001, 20, 'Le Conseil national de l''éducation doit être maintenu.', 'education'),
  (10021, 10001, 21, 'L''assurance maladie doit couvrir toute la population.', 'sante'),
  (10022, 10001, 22, 'Les nouveaux hôpitaux publics doivent être gérés par des opérateurs privés.', 'sante'),
  (10023, 10001, 23, 'La loi de 2017 sur l''embauche doit être maintenue telle quelle.', 'emploi'),
  (10024, 10001, 24, 'Les données sensibles de l''État et des citoyens doivent être hébergées au Bénin ou sous le contrôle de l''État.', 'numerique'),
  (10025, 10001, 25, 'Le budget de la défense doit augmenter progressivement au cours des dix prochaines années.', 'securite');
insert into public.party_position (statement_id, org_id, position, source_type, source_url, source_extrait, date_source) values
  (10001, 10001, 'accord', 'document_public', 'https://portailpartispolitiques.bj/wp-content/uploads/2020/01/UNION-PROGRESSISTE-PROJET-DE-SOCIETE.pdf', 'Avec la réforme en profondeur du système partisan, sous l’impulsion du Président Patrice TALON, qui en a fait l’une des réformes phares du Programme d’Action de son Gouvernement (PAG), le Bénin entre de plain-pied dans la recomposition de ses forces politiques.', '2018-12-01'),
  (10001, 10002, 'accord', 'document_public', 'https://web.archive.org/web/20240305112738id_/https://www.blocrepublicain.co/storage/2020/08/STATUTS-BLOC-REPUBLICAIN.pdf', 'l''expérience vécue ces dernières années a montré à suffisance les limites du système du multipartisme dans notre pays. […] la loi n°2018-23 du 17 septembre 2018 portant charte des partis politiques en République du Bénin, expression de la volonté politique des pouvoirs publics de corriger le système partisan', '2018-12-08'),
  (10001, 10003, 'desaccord', 'document_public', 'https://lesdemocratesbenin.com/wp-content/uploads/2023/09/STATUTS-LES-DEMOCRATES.pdf', 'Le multipartisme intégral consacré par la constitution du 11 décembre 1990 a vite fait place à un système partisan contrôlé.', '2020-11-17'),
  (10001, 10004, 'sans_position', 'aucune', null, null, null),
  (10001, 10005, 'sans_position', 'aucune', null, null, null),
  (10001, 10006, 'sans_position', 'aucune', null, null, null),
  (10001, 10007, 'accord', 'document_public', 'https://pub-f2abea1e4da540aa9a3e39fedb257f21.r2.dev/PROGRAMME-WADAGNI-TALATA-2026.pdf', 'La réforme du système partisan ayant conduit à un regroupement des forces politiques et à l’amélioration de leur financement pour un meilleur impact sur le plan national', '2026-03-21'),
  (10001, 10008, 'desaccord', 'document_public', 'https://www.les4verites.bj/wp-content/uploads/2026/03/PROJET-DE-SOCIETE-FCBE-montage-complet-1.pdf', 'Code électoral et charte des partis politiques crisogènes ; […] Relire le code électoral et la charte des partis politiques', '2026-03-27'),
  (10002, 10001, 'sans_position', 'aucune', null, null, null),
