  (10003, 10007, 'accord', 'document_public', 'https://pub-f2abea1e4da540aa9a3e39fedb257f21.r2.dev/PROGRAMME-WADAGNI-TALATA-2026.pdf', 'Le renforcement de la représentation des femmes en politique, grâce à la mesure adoptée en 2019 leur réservant un siège par circonscription électorale, et portant le nombre de femmes députés de 6 à au moins 28 sur 109 membres de l’Assemblée nationale', '2026-03-21'),
  (10003, 10008, 'sans_position', 'aucune', null, null, null),
